contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address rewardToken, uint256 amount) public {
        // Set a distributor that is definitely not this test contract.
        c.setRewardDistributor(address(1));

        // As owner, register the reward token (fresh contract, so it cannot already exist).
        c.addReward(rewardToken);
        uint40 finishBefore = c.rewardPeriodFinish(rewardToken);

        // Non-distributor must not be able to notify rewards.
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && c.rewardPeriodFinish(rewardToken) == finishBefore);
    }

    receive() external payable {}
}

