contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newDistributor) public {
        // Current distributor must survive the failed update
        address currentDistributor = c.rewardDistributor();

        // Renounce ownership so no one can call the owner-gated setter anymore
        c.renounceOwnership();

        // The owner-gated setter must now revert for any input address
        bool reverted;
        try c.setRewardDistributor(newDistributor) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Rule: after renouncing, setRewardDistributor always reverts and
        // the reward distributor remains exactly what it was before.
        assert(reverted && c.rewardDistributor() == currentDistributor);
    }

    receive() external payable {}
}

