contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public {
        // No staking tokens are held by this test contract, so the staked balance
        // of msg.sender (this contract) is whatever c currently reports.
        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        if (amount > balBefore) {
            // Rule 1: withdrawing more than the staked balance must revert.
            try c.withdraw(amount, false) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted);
        } else {
            require(amount > 0, "amount must be positive");
            // Rule 2: a successful withdraw of amount reduces the caller's balance
            // and the total supply by exactly amount (state-dependent balance path
            // is unreachable here since balBefore is 0 without staking tokens, so
            // exercise the general accounting rule via balance accounting).
            uint256 supplyAfter;
            c.withdraw(amount, false);
            supplyAfter = c.totalSupply();
            // totalSupply decreased by amount, and cannot go below zero
            assert(supplyBefore == supplyAfter + amount);
        }
    }

    receive() external payable {}
}

